import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Z.AI / GLM (BYOK Provider)","description":"","frontmatter":{"title":"Z.AI / GLM (BYOK Provider)"},"headers":[],"relativePath":"providers/zai.md","filePath":"providers/zai.md"}`),a={name:`providers/zai.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="z-ai-glm-mode-byok" tabindex="-1">Z.AI / GLM (Mode BYOK) <a class="header-anchor" href="#z-ai-glm-mode-byok" aria-label="Permalink to “Z.AI / GLM (Mode BYOK)”">​</a></h1><p><strong>Z.AI</strong> (dari Zhipu AI) menjalankan keluarga model <strong>GLM</strong> — pilihan menarik untuk BYOK karena harga flagship-nya relatif ramah di kantong, ada beberapa <strong>model gratis murni</strong> (bukan trial credit) yang bisa langsung dipakai tanpa top-up, dan API-nya berformat <em>OpenAI-compatible</em>. Keluarga modelnya beragam: mulai yang ringan dan cepat untuk chat harian sampai flagship yang bertenaga besar untuk <em>roleplay</em> panjang. Kalau kamu baru mengenal BYOK, baca dulu <a href="./../byok/">Pengenalan BYOK</a>.</p><div class="warning custom-block"><p class="custom-block-title">📅 Info penting 2026</p><p>Nama model, harga, dan aturan gratis-langganan Z.AI berubah cukup sering. Halaman ini mengajarkan <strong>cara</strong> yang benar, bukan daftar harga — angka yang disebut hanyalah contoh. Selalu cek halaman resmi <a href="https://docs.z.ai/guides/overview/pricing" target="_blank" rel="noreferrer">harga GLM</a> sebelum menetapkan budget.</p></div><hr><h2 id="membuat-api-key" tabindex="-1">Membuat API Key <a class="header-anchor" href="#membuat-api-key" aria-label="Permalink to “Membuat API Key”">​</a></h2><ol><li>Daftar di <a href="https://chat.z.ai" target="_blank" rel="noreferrer">z.ai/chat</a> dengan email atau Google.</li><li>Klik <strong>menu profil</strong>, buka bagian <strong>API Keys</strong>.</li><li>Klik <strong>Create a new API key</strong>, beri nama, lalu salin key yang ditampilkan.</li></ol><div class="tip custom-block"><p class="custom-block-title">🔐 Bedanya dengan provider lain: key bisa dilihat ulang</p><p>Berbeda dengan Gemini atau Claude yang hanya menampilkan key <strong>sekali</strong>, key Z.AI <strong>bisa dilihat dan di-copy ulang kapan saja</strong> dari <a href="https://z.ai/manage-apikey/apikey-list" target="_blank" rel="noreferrer">halaman API Keys</a>. Ini membuat rotasi dan pemulihan key jadi jauh lebih ramah — tapi <strong>tetap simpan dengan aman</strong> (password manager) dan jangan pernah menempelkan key ke chat, forum, atau screenshot. Key yang bocor = saldo kredit-mu bisa dipakai orang lain.</p></div><hr><h2 id="mengaktifkan-z-ai-di-mikazuki-ai" tabindex="-1">Mengaktifkan Z.AI di Mikazuki AI <a class="header-anchor" href="#mengaktifkan-z-ai-di-mikazuki-ai" aria-label="Permalink to “Mengaktifkan Z.AI di Mikazuki AI”">​</a></h2><p>Ikuti alur BYOK standar dari panduan <a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a>. Ringkasannya untuk Z.AI:</p><ol><li>Buka <strong>Settings → Engine</strong>, pilih mode <strong>BYOK</strong>.</li><li>Pada pilihan provider, pilih <strong>ZAI</strong>.</li><li>Tempel API key yang barusan kamu buat.</li><li>Klik tombol 🔍 <strong>fetch models</strong> — daftar model akan muncul otomatis dari key kamu.</li><li>Pilih model, atur <a href="./../byok/parameter-dasar.html">Parameter Dasar</a> — terutama <code>context_window</code> — lalu klik simpan.</li></ol><p>Worker Mikazuki memakai <strong>provider native ZAI</strong> dengan <strong>endpoint tetap (fixed)</strong>, jadi tidak ada kolom <em>Base URL</em> yang perlu kamu isi. Sebagai referensi, endpoint-nya mengikuti format <em>OpenAI-compatible</em> di <code>https://api.z.ai/api/paas/v4</code> — tapi tetap pilih provider <strong>ZAI</strong> di Mikazuki, bukan jalur <em>OpenAI Compatible</em> manual.</p><div class="tip custom-block"><p class="custom-block-title">Sudah baik dari sananya</p><p>Default <strong>temperature 0.85</strong> Mikazuki sudah dipetakan dengan baik untuk roleplay; kamu tidak perlu mengubahnya kecuali memang ingin gaya jawaban yang sangat berbeda.</p></div><hr><h2 id="model-glm-varian" tabindex="-1">Model GLM &amp; Varian <a class="header-anchor" href="#model-glm-varian" aria-label="Permalink to “Model GLM &amp; Varian”">​</a></h2><p>Keluarga model GLM yang kemungkinan besar kamu temui di daftar fetch models:</p><table tabindex="0"><thead><tr><th>Grup</th><th>Contoh nama</th><th>Cocok untuk</th></tr></thead><tbody><tr><td><strong>Flagship</strong></td><td><code>glm-5.3</code></td><td>kualitas tulisan terbaik, <em>roleplay</em> berat</td></tr><tr><td><strong>Hemat &amp; cepat</strong></td><td><code>glm-5.3-flash</code>, <code>glm-5.3-flashx</code></td><td>chat harian, respons cepat</td></tr><tr><td><strong>Generasi sebelumnya</strong></td><td><code>glm-5.2</code>, <code>glm-5</code></td><td>alternatif kalau flagship sedang bermasalah</td></tr><tr><td><strong>Gratis murni (teks)</strong></td><td><code>glm-4.7-flash</code>, <code>glm-4.5-flash</code></td><td>mencoba tanpa biaya</td></tr><tr><td><strong>Gratis murni (vision)</strong></td><td><code>glm-4.6v-flash</code></td><td>input gambar tanpa biaya</td></tr></tbody></table><p>Tiga model <strong>gratis murni</strong> (bukan trial credit yang bisa habis): <code>glm-4.7-flash</code> dan <code>glm-4.5-flash</code> untuk teks, serta <code>glm-4.6v-flash</code> untuk vision. Semuanya <em>rate-limited</em> dan dioptimalkan untuk kecepatan — pas untuk mencoba-coba dan chat ringan.</p><p>Ambil nama model <strong>persis dari daftar fetch models</strong> — ketik manual mudah salah ejaan.</p><hr><h2 id="free-tier-harga-coding-plan" tabindex="-1">Free Tier, Harga &amp; Coding Plan <a class="header-anchor" href="#free-tier-harga-coding-plan" aria-label="Permalink to “Free Tier, Harga &amp; Coding Plan”">​</a></h2><ul><li><strong>Tanpa kartu kredit untuk mencoba</strong>: akun baru biasanya mendapat <strong>kredit percobaan awal</strong> kecil (trial); cek jumlahnya di dasbor.</li><li><strong>Model gratis murni</strong>: tiga model Flash/V-Flash di tabel di atas bisa dipakai <strong>tanpa bayar sama sekali</strong> (dengan limit pemakaian).</li><li><strong>Top-up kredit</strong> untuk model berbayar: pemakaian API memotong saldo kredit-mu.</li></ul><p>Soal harga: flagship <code>glm-5.3</code> sebagai contoh publik berada di kisaran <strong>$1,4 per juta token input / $4,4 per juta token output</strong>. Semua harga bisa berubah kapan saja, jadi ini hanya contoh kerangka biaya — <strong>cek <a href="https://docs.z.ai/guides/overview/pricing" target="_blank" rel="noreferrer">halaman harga resmi GLM</a></strong> untuk angka terkini.</p><div class="tip custom-block"><p class="custom-block-title">💡 Cached input jauh lebih murah</p><p>Perhatikan tarif <em>cached input</em> di halaman pricing: token input yang dibaca dari <em>cache</em> berbiaya <strong>jauh lebih murah</strong> daripada input segar — untuk <code>glm-5.3</code>, tarif cache-nya sekitar <strong>$0,26 per juta token</strong> (contoh, bisa berubah). Percakapan roleplay panjang yang mengirim ulang konteks tiap pesan bisa memanfaatkan tarif ini — hitung biaya berdasarkan <em>string cache-difference</em>, bukan total prompt.</p></div><div class="danger custom-block"><p class="custom-block-title">⚠️ GLM Coding Plan ≠ API umum</p><p>Z.AI juga menjual langganan bernama <strong>GLM Coding Plan</strong> — tapi itu <strong>khusus untuk tool coding</strong> (Claude Code, OpenCode, dan sejenisnya), <strong>BUKAN</strong> untuk API umum. Untuk BYOK Mikazuki, yang kamu butuhkan adalah <strong>API key biasa + top-up kredit</strong>, bukan Coding Plan. Jangan sampai salah beli langganan yang tujuannya berbeda.</p></div><div class="warning custom-block"><p class="custom-block-title">⚠️ Jangan kunci angka untuk model lain</p><p>Kami sengaja tidak mencantumkan harga untuk model Flash/FlashX dsb — sumber angkanya bertabrakan dan cepat basi. Tinjau <a href="https://docs.z.ai/guides/overview/pricing" target="_blank" rel="noreferrer">halaman harga resmi</a> sebelum budgeting, dan monitor sisa kreditmu di dasbor Z.AI.</p></div><hr><h2 id="rate-limit-kredit" tabindex="-1">Rate Limit &amp; Kredit <a class="header-anchor" href="#rate-limit-kredit" aria-label="Permalink to “Rate Limit &amp; Kredit”">​</a></h2><ul><li><strong>Tidak ada angka publik resmi per tier</strong>: limit dihitung per akun dan per plan, dan angkanya bisa berubah — jadi kami tidak menguncinya di sini.</li><li><strong>Rule of thumb</strong>: model <strong>gratis</strong> punya rate limit paling ketat; model berbayar lebih longgar seiring plan/top-up.</li><li>Kalau request terlalu cepat berurutan, API merespons <strong>429</strong> — perlakukan ini sebagai &quot;perlambat sebentar&quot; lalu coba lagi (<em>backoff</em>), bukan sinyal untuk spam retry.</li></ul><hr><h2 id="privasi-data" tabindex="-1">Privasi &amp; Data <a class="header-anchor" href="#privasi-data" aria-label="Permalink to “Privasi &amp; Data”">​</a></h2><p>Z.AI adalah penyedia yang <strong>basisnya di Tiongkok (China)</strong>. Untuk kamu yang peduli residensi data, jelajahi kebijakannya secara netral: data diproses oleh server Z.AI sesuai <strong>kebijakan privasi mereka sendiri</strong> — baca <a href="https://z.ai/privacypolicy" target="_blank" rel="noreferrer">kebijakan privasi resmi z.ai</a> sebelum memutuskan memakai API-nya untuk konten pribadi.</p><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><p>Z.AI mengembalikan kode detail yang cukup informatif — cocokkan pesan error-mu dengan ini:</p><details class="details custom-block"><summary>Error 401 dengan code 1000 — Authentication Failed</summary><p>Key-nya salah, sudah di-revoke, atau ter-gap spasi saat copy. Buka <a href="https://z.ai/manage-apikey/apikey-list" target="_blank" rel="noreferrer">halaman API Keys</a>, untungnya key Z.AI <strong>bisa dilihat ulang</strong> — bandingkan karakter demi karakter di sana, atau regenerasi langsung key baru dan tempel ulang di Mikazuki.</p></details><details class="details custom-block"><summary>Error 401 dengan code 1003 — token expired</summary><p>Key kamu sudah kedaluwarsa. Buat <strong>key baru</strong> dari halaman API Keys dan ganti di Settings Mikazuki.</p></details><details class="details custom-block"><summary>Error 429 dengan code 1113 — Insufficient balance / no resource package</summary><p>Saldo kredit kamu habis atau paket resource-nya tidak aktif. Top-up kredit di dasbor Z.AI, lalu ulangi request-nya. Kalau kamu pikir masih ada kredit trial, cek jumlahnya di dasbor — kredit percobaan memang biasanya kecil.</p></details><details class="details custom-block"><summary>Error 429 dengan code 1302 — rate limit</summary><p>Kamu mengirim terlalu sering. Perlambat intensitas request dan pakai <em>backoff</em> (tunggu sebentar, coba lagi). Di model gratis limit paling ketat — kalau sering kena, pindahkan chat utama ke model berbayar.</p></details><details class="details custom-block"><summary>Error 400 dengan code 1211 — Unknown Model</summary><p>Nama model salah ejaan. Ambil nama <strong>persis</strong> dari daftar fetch models di Mikazuki — seperti <code>glm-5.3</code>, <code>glm-5.3-flash</code>, atau <code>glm-4.7-flash</code> — jangan ketik manual dari ingatan.</p></details><hr><h2 id="jelajahi-byok-lebih-lanjut" tabindex="-1">Jelajahi BYOK Lebih Lanjut <a class="header-anchor" href="#jelajahi-byok-lebih-lanjut" aria-label="Permalink to “Jelajahi BYOK Lebih Lanjut”">​</a></h2><ul><li><a href="./../byok/">Pengenalan BYOK</a> — konsep dasar dan cara kerjanya.</li><li><a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a> — langkah menyalakan mode BYOK.</li><li><a href="./../byok/parameter-dasar.html">Parameter Dasar</a> — atur <code>max_tokens</code>, <code>context_window</code>, dan parameter kreativitas.</li><li><a href="./gemini.html">Google Gemini</a> — panduan padanan untuk provider Gemini.</li><li><a href="./claude.html">Anthropic Claude</a> — panduan padanan untuk provider Claude.</li><li><a href="./systemai.html">System AI</a> — kalau kamu tidak ingin mengurus key dan pembayaran API sendiri.</li></ul>`,43)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};